package com.rulecraft.decisionops.workflow.domain;
import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="decision_change_request")
public class DecisionChangeRequest {@Id private UUID id;@Column(name="tenant_id",nullable=false)private UUID tenantId;@Column(name="project_id",nullable=false)private UUID projectId;@Column(name="decision_service_id",nullable=false)private UUID serviceId;@Column(name="decision_version_id",nullable=false)private UUID decisionVersionId;@Column(name="client_request_id",nullable=false)private UUID clientRequestId;@Column(name="request_number",nullable=false)private int requestNumber;@Column(nullable=false,length=160)private String title;@Column(length=2000)private String summary;@Enumerated(EnumType.STRING)@Column(nullable=false,length=32)private ChangeRequestState state;@Column(name="created_by",nullable=false)private UUID createdBy;@Column(name="created_by_name",nullable=false,length=160)private String createdByName;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;@Version private long version;protected DecisionChangeRequest(){}public DecisionChangeRequest(UUID tenantId,UUID projectId,UUID serviceId,UUID decisionVersionId,UUID clientRequestId,int number,String title,String summary,UUID actor,String actorName,Instant now){id=UUID.randomUUID();this.tenantId=tenantId;this.projectId=projectId;this.serviceId=serviceId;this.decisionVersionId=decisionVersionId;this.clientRequestId=clientRequestId;requestNumber=number;this.title=title;this.summary=summary;state=ChangeRequestState.DRAFT;createdBy=actor;createdByName=actorName;createdAt=now;updatedAt=now;}public void transition(ChangeRequestState next,Instant now){state=next;updatedAt=now;}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getProjectId(){return projectId;}public UUID getServiceId(){return serviceId;}public UUID getDecisionVersionId(){return decisionVersionId;}public UUID getClientRequestId(){return clientRequestId;}public int getRequestNumber(){return requestNumber;}public String getTitle(){return title;}public String getSummary(){return summary;}public ChangeRequestState getState(){return state;}public UUID getCreatedBy(){return createdBy;}public String getCreatedByName(){return createdByName;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public long getVersion(){return version;}}
